const $=s=>document.querySelector(s),canvas=$('#field'),ctx=canvas.getContext('2d');
const colors=['#849178','#9bdfb0','#ed8976'], names=['HOME','REDKEEP','RIDGE','LOWLAND','NORTHWATCH','CROSSROADS','SOUTHWATCH','QUARRY','RELAY'];
const params=new URLSearchParams(location.search);let seed=/^\d{1,9}$/.test(params.get('seed')||'')?Number(params.get('seed')):crypto.getRandomValues(new Uint32Array(1))[0]%999999999;
let difficulty=['easy','normal','hard'].includes(params.get('bot'))?params.get('bot'):'normal';$('#difficulty').value=difficulty;
const targetScore=Math.max(0,Math.min(100000,Number(params.get('score'))||0));
let state,selected=-1,hover=-1,keyboard=0,fraction=.5,started=false,paused=false,ready=false,last=0,accumulator=0,finished=false,score=0,toastTimer,w=1000,h=600;
let best=0;try{best=Number(localStorage.getItem('gamat-best'))||0}catch{}updateBest();
function updateBest(){$('#best strong').textContent=best?best.toLocaleString()+' PTS':'—'}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function reset(newSeed=false){if(!ready)return;if(newSeed)seed=crypto.getRandomValues(new Uint32Array(1))[0]%999999999;difficulty=$('#difficulty').value;state=JSON.parse(gamatNew(String(seed),difficulty));selected=-1;started=false;paused=false;finished=false;score=0;accumulator=0;$('#pause').textContent='Ⅱ';$('#pause').setAttribute('aria-label','Pause game');setOverlay('WELCOME, COMMANDER',targetScore?'A score to settle.':'Nine outposts.<br>One winner.',targetScore?`Your friend scored ${targetScore.toLocaleString()} points. Same battlefield, same bot. Your turn.`:'Capture neutral territory, reinforce your lines, and eliminate the red army.','Deploy forces',begin);$('#seed-label').textContent=`Skirmish / Seed ${String(seed).padStart(6,'0')}`;updateHUD()}
function setOverlay(eyebrow,title,description,label,action){$('#overlay').classList.remove('hidden');const panel=$('#overlay .overlay-panel');panel.replaceChildren();let e=document.createElement('span');e.className='eyebrow';e.textContent=eyebrow;panel.append(e);let titleEl=document.createElement('h2');titleEl.innerHTML=title;panel.append(titleEl);let p=document.createElement('p');p.textContent=description;panel.append(p);let b=document.createElement('button');b.className='primary';b.textContent=label;b.onclick=action;panel.append(b);let small=document.createElement('small');small.textContent='5 minute matches · No account needed';panel.append(small)}
function begin(){started=true;paused=false;last=performance.now();$('#overlay').classList.add('hidden');canvas.focus()}
function pause(){if(!started||finished)return;paused=!paused;$('#pause').textContent=paused?'▶':'Ⅱ';$('#pause').setAttribute('aria-label',paused?'Resume game':'Pause game');if(paused)setOverlay('HOLDING POSITION','Take a breath.','Your forces will hold until you return.','Resume operation',pause);else $('#overlay').classList.add('hidden')}
function updateHUD(){if(!state)return;const own=state.nodes.filter(n=>n.owner===1),enemy=state.nodes.filter(n=>n.owner===2);$('#player-count').textContent=own.length;$('#bot-count').textContent=enemy.length;let sec=Math.max(0,Math.ceil(300-state.time));$('#timer').textContent=`${Math.floor(sec/60).toString().padStart(2,'0')}:${(sec%60).toString().padStart(2,'0')}`;let n=state.nodes[selected];$('#node-title').textContent=n?names[n.id].toLowerCase().replace(/^./,c=>c.toUpperCase()):'Your next move.';$('#node-description').textContent=n?`Level ${n.level} outpost · ${n.owner===1?'Your territory':n.owner===2?'Enemy territory':'Neutral territory'}`:'Select a teal outpost to inspect your forces and issue an order.';$('#garrison').textContent=n?Math.floor(n.units):'—';$('#production').textContent=n?`${n.owner===0?0:(1.35*n.level).toFixed(1)}/s`:'—';$('#upgrade').disabled=!n||n.owner!==1||n.units<n.level*20||n.level>=3||!started||paused||finished;$('#upgrade-cost').textContent=n?.level===3?'Max level':`${(n?.level||1)*20} troops`;if(n&&n.owner!==1)selected=-1}
function end(){finished=true;const win=state.status==='victory';score=Math.round((win?1000:0)+state.captures*100+state.nodes.filter(n=>n.owner===1).reduce((a,n)=>a+n.units+n.level*40,0)+(win?Math.max(0,300-state.time)*10:0));if(score>best){best=score;try{localStorage.setItem('gamat-best',String(best))}catch{}updateBest()};setOverlay(win?'OPERATION COMPLETE':state.status==='draw'?'CEASEFIRE':'OPERATION LOST',win?'The field is yours.':state.status==='draw'?'An even match.':'Regroup. Rethink.',`${score.toLocaleString()} points · ${state.captures} captures${targetScore?` · ${score>targetScore?'You beat the challenge!':'Target: '+targetScore.toLocaleString()}`:''}. ${win?'Share your score or run it back.':'Try expanding earlier and keeping reserves.'}`,'Play again',()=>{reset();begin()});toast(win?'Victory. Well commanded.':'Match complete. Your score is ready to share.')}
function order(id){if(!started||paused||finished)return;if(id<0){selected=-1;return}let n=state.nodes[id];if(selected>=0&&selected!==id&&state.nodes[selected].owner===1){if(gamatSend(selected,id,fraction)){toast(`Deploying ${Math.floor(state.nodes[selected].units*fraction)} troops to ${names[id].toLowerCase()}`);state=JSON.parse(gamatStep(0));selected=-1}else toast('Not enough troops to deploy.')}else selected=n.owner===1?id:-1;updateHUD()}
function upgrade(){if($('#upgrade').disabled)return;if(gamatUpgrade(selected)){state=JSON.parse(gamatStep(0));toast('Outpost upgraded. Production increased.');updateHUD()}}
function resize(){const r=canvas.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);canvas.width=r.width*d;canvas.height=r.height*d;w=r.width;h=r.height;draw(performance.now())}new ResizeObserver(resize).observe(canvas);
function world(e){const r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left)/r.width*1000,y:(e.clientY-r.top)/r.height*600}}
function hit(p){return state?state.nodes.findIndex(n=>Math.hypot(n.x-p.x,n.y-p.y)<48):-1}
canvas.addEventListener('pointermove',e=>{hover=hit(world(e));canvas.style.cursor=hover>=0?'pointer':'crosshair'});canvas.addEventListener('pointerleave',()=>hover=-1);canvas.addEventListener('pointerdown',e=>{e.preventDefault();canvas.focus();order(hit(world(e)))});
canvas.addEventListener('keydown',e=>{if(['ArrowRight','ArrowDown','ArrowLeft','ArrowUp'].includes(e.code)){e.preventDefault();keyboard=(keyboard+(['ArrowRight','ArrowDown'].includes(e.code)?1:8))%9;hover=keyboard}else if(e.code==='Enter'){e.preventDefault();order(keyboard)}else if(e.code==='Escape'){selected=-1;updateHUD()}});
document.addEventListener('keydown',e=>{if(e.target.matches('input,select,button')||document.querySelector('dialog[open]'))return;if(e.code==='Space'){e.preventDefault();pause()}if(e.code==='KeyU')upgrade()});
$('#fractions').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;fraction=Number(b.dataset.value);$('#fractions .active').classList.remove('active');b.classList.add('active');$('#fraction-label').textContent=`${fraction*100}%`});$('#upgrade').onclick=upgrade;$('#pause').onclick=pause;
$('#new-game').onclick=()=>{reset(true);begin()};$('#difficulty').onchange=()=>{reset();toast('Opponent changed. Deploy when ready.')};
function modal(id){const wasRunning=started&&!paused&&!finished;if(wasRunning)pause();const dialog=$(id);dialog.showModal();dialog.addEventListener('close',()=>{if(wasRunning&&paused)pause()},{once:true})}
$('#help').onclick=()=>modal('#help-dialog');document.querySelectorAll('dialog .close, .close-help').forEach(b=>b.onclick=()=>b.closest('dialog').close());
$('#share').onclick=()=>{const url=new URL(location.href);url.search='';url.searchParams.set('seed',String(seed));url.searchParams.set('bot',difficulty);if(finished)url.searchParams.set('score',String(score));$('#share-url').value=url.href;modal('#share-dialog')};
$('#copy-link').onclick=async()=>{try{await navigator.clipboard.writeText($('#share-url').value);toast('Challenge link copied. Send it to your friend.')}catch{$('#share-url').select();toast('Select and copy the challenge link.')}};
document.addEventListener('visibilitychange',()=>{if(document.hidden&&started&&!paused&&!finished)pause()});
function circle(x,y,r,fill,stroke,line=1){ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);if(fill){ctx.fillStyle=fill;ctx.fill()}if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=line;ctx.stroke()}}
function draw(now){ctx.setTransform(canvas.width/1000,0,0,canvas.height/600,0,0);ctx.fillStyle='#15271f';ctx.fillRect(0,0,1000,600);
// A quiet tactical grid, contour lines, and hand-drawn terrain keep the board legible.
ctx.strokeStyle='#a2b88809';ctx.lineWidth=1;for(let x=0;x<1000;x+=40){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,600);ctx.stroke()}for(let y=0;y<600;y+=40){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(1000,y);ctx.stroke()}
for(let i=0;i<5;i++){ctx.beginPath();for(let x=-30;x<=1030;x+=10){let y=285+Math.sin(x*.007+1)*45+Math.sin(x*.018)*13+i*9;x===-30?ctx.moveTo(x,y):ctx.lineTo(x,y)}ctx.strokeStyle=i===2?'#81a98c0e':'#81a98c06';ctx.lineWidth=2;ctx.stroke()}
for(let i=0;i<110;i++){let x=(i*137.7+30)%1000,y=(i*91.3+80)%600;if(state&&state.nodes.some(n=>Math.hypot(n.x-x,n.y-y)<65))continue;ctx.fillStyle=i%4===0?'#48634444':'#304d383b';ctx.beginPath();ctx.moveTo(x,y-6);ctx.lineTo(x-4,y+3);ctx.lineTo(x+4,y+3);ctx.closePath();ctx.fill()}
if(!state)return;ctx.setLineDash([3,9]);ctx.lineWidth=1;for(let i=0;i<state.nodes.length;i++)for(let j=i+1;j<state.nodes.length;j++){let a=state.nodes[i],b=state.nodes[j];if(Math.hypot(a.x-b.x,a.y-b.y)>350)continue;ctx.strokeStyle='#a7b89813';ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke()}ctx.setLineDash([]);
if(selected>=0&&hover>=0&&selected!==hover){let a=state.nodes[selected],b=state.nodes[hover];ctx.strokeStyle='#9bdfb088';ctx.setLineDash([6,6]);ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();ctx.setLineDash([])}
for(const f of state.fleets){const a=state.nodes[f.from],b=state.nodes[f.to],x=a.x+(b.x-a.x)*f.progress,y=a.y+(b.y-a.y)*f.progress,angle=Math.atan2(b.y-a.y,b.x-a.x);ctx.save();ctx.translate(x,y);ctx.rotate(angle);ctx.fillStyle=colors[f.owner];ctx.beginPath();ctx.moveTo(8,0);ctx.lineTo(-5,-5);ctx.lineTo(-2,0);ctx.lineTo(-5,5);ctx.closePath();ctx.fill();ctx.restore();ctx.fillStyle=colors[f.owner];ctx.font='600 11px "DM Sans",sans-serif';ctx.textAlign='center';ctx.fillText(f.units,x,y-12)}
for(const n of state.nodes){let c=colors[n.owner],r=n.id<2?37:30,isSelected=selected===n.id;circle(n.x,n.y,r+8,null,isSelected?c:c+'22',isSelected?2:1);if(isSelected){circle(n.x,n.y,r+15,null,c+'33');ctx.strokeStyle=c;ctx.lineWidth=2;ctx.beginPath();ctx.arc(n.x,n.y,r+15,now*.001,now*.001+1);ctx.stroke()}if(hover===n.id)circle(n.x,n.y,r+12,null,c+'66');ctx.save();ctx.shadowBlur=n.owner?20:0;ctx.shadowColor=c+'33';circle(n.x,n.y,r,n.owner===1?'#294b35':n.owner===2?'#49372b':'#27382b',c+'88',1.5);ctx.restore();ctx.fillStyle=c;ctx.textAlign='center';ctx.font='600 23px "Barlow Condensed",sans-serif';ctx.fillText(Math.floor(n.units),n.x,n.y+7);for(let l=0;l<n.level;l++)circle(n.x+(l-(n.level-1)/2)*7,n.y+r-9,1.5,c);ctx.fillStyle=n.owner?c+'cc':'#899c7c';ctx.font='500 8px "DM Sans",sans-serif';ctx.fillText(names[n.id],n.x,n.y+r+26);if(n.owner>0){ctx.font='8px "DM Sans",sans-serif';ctx.fillStyle=c+'88';ctx.fillText(n.owner===1?'FRIENDLY':'HOSTILE',n.x,n.y-r-17)}}
}
function frame(now){let dt=last?Math.min((now-last)/1000,.1):0;last=now;if(ready&&started&&!paused&&!finished){accumulator+=dt;while(accumulator>=.05){state=JSON.parse(gamatStep(.05));accumulator-=.05;if(state.status!=='playing'){end();break}}updateHUD()}draw(now);requestAnimationFrame(frame)}requestAnimationFrame(frame);
async function boot(){try{const go=new Go();const response=await fetch('game.wasm');if(!response.ok)throw Error('Engine download failed');const wasm=await WebAssembly.instantiate(await response.arrayBuffer(),go.importObject);go.run(wasm.instance).catch(e=>{toast('Engine stopped. Reload to restart.');console.error(e)});ready=true;$('#new-game').disabled=false;reset();}catch(e){console.error(e);setOverlay('ENGINE UNAVAILABLE','We hit a snag.','The Go engine could not load. Check your connection and try again.','Reload',()=>location.reload())}}boot();
